import type { PropsWithChildren } from "react";
import { Drawer, DrawerContent } from "@/components/ui/drawer";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { useState } from "react";
import { useStore } from "@nanostores/react";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Switch } from "@/components/ui/switch";
import { persistentAtom } from "@nanostores/persistent"

export type Preferences = {
  alreadyChosen: boolean;
  ad_storage: 'granted' | 'denied';           // Storage for advertising
  analytics_storage: 'granted' | 'denied';    // Storage for analytics
  functionality_storage: 'granted' | 'denied'; // Storage for functionality
  personalization_storage: 'granted' | 'denied'; // Storage for personalization
  security_storage: 'granted' | 'denied';     // Storage for security
}

const preferencesState = persistentAtom<Preferences>('cookies-preferences', {
  alreadyChosen: false,
  'ad_storage': 'denied',           // Storage for advertising
  'analytics_storage': 'denied',    // Storage for analytics
  'functionality_storage': 'denied', // Storage for functionality
  'personalization_storage': 'denied', // Storage for personalization
  'security_storage': 'denied',     // Storage for security
}, { encode: JSON.stringify, decode: JSON.parse });

const grantedAll = () => {
  preferencesState.set({
    alreadyChosen: true,
    'ad_storage': 'granted',
    'analytics_storage': 'granted',
    'functionality_storage': 'granted',
    'personalization_storage': 'granted',
    'security_storage': 'granted',
  });
}

const deniedAll = () => {
  preferencesState.set({
    alreadyChosen: true,
    'ad_storage': 'denied',
    'analytics_storage': 'denied',
    'functionality_storage': 'denied',
    'personalization_storage': 'denied',
    'security_storage': 'denied',
  });
}

export function CookieDialogSettings(
  props: PropsWithChildren<{ className?: string }>,
) {
  const { children, className } = props;

  const preferences = useStore(preferencesState);

  const allAccepted = preferences.ad_storage === 'granted' &&
    preferences.analytics_storage === 'granted' &&
    preferences.functionality_storage === 'granted' &&
    preferences.personalization_storage === 'granted' &&
    preferences.security_storage === 'granted';

  const marketingAccepted = preferences.ad_storage === 'granted';
  const statisticsAccepted = preferences.analytics_storage === 'granted';
  const preferencesAccepted = preferences.personalization_storage === 'granted';

  return (
    <aside className={className}>
      <Dialog>
        <DialogTrigger>{children}</DialogTrigger>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Centro de preferencias de la privacidad</DialogTitle>
            <DialogDescription></DialogDescription>
          </DialogHeader>
          <div className="mb-2">
            <p className="mb-4">
              A continuación te mostramos el detalle de las cookies que tenemos
              en la web de Universia Holding. La información la encontrarás
              detallada en relación con la finalidad de las cookies. Podrás
              configurar o instalar aquellas que consideres adecuadas o
              rechazarlas todas. Recuerda que las cookies técnicas se instalarán
              siempre ya que sin ellas la web no puede funcionar correctamente.
              Haz clic en los encabezados de cada categoría para saber más y
              cambiar la configuración como desees. Sin embargo, ten en cuenta
              que el bloqueo de algunos tipos de cookies puede afectar su
              experiencia en el sitio y los servicios que podemos ofrecer. Puede
              consultar nuestra política de cookies en cualquier momento en la
              Web o{" "}
              <a href="/legal/cookies" className="text-blue-500">
                aquí
              </a>
              .
            </p>
            {!allAccepted && (
              <Button
                variant={"destructive"}
                size={"lg"}
                onClick={() => {
                  grantedAll();
                }}
              >
                Permitir todas
              </Button>
            )}
          </div>
          <h3 className="text-lg">
            Gestionar las preferencias de consentimiento
          </h3>
          <div>
            <Accordion type="single" collapsible className="w-full">
              <AccordionItem value="necessary">
                <AccordionTrigger>
                  <span>
                    Necesarias{" "}
                    <Badge variant="secondary">Siempre activadas</Badge>
                  </span>
                </AccordionTrigger>
                <AccordionContent>
                  <div className="flex flex-row justify-between gap-4">
                    <p>
                      Estas cookies son necesarias para asegurar la navegación a
                      través del Site y la utilización de las diferentes
                      opciones o servicios que se ofrecen (permiten, por
                      ejemplo, identificar la sesión, acceder a partes de acceso
                      restringido, utilizar elementos de seguridad durante la
                      navegación, etc.). También nos permiten obtener
                      estadísticas anónimas sobre la navegación en el Site.
                    </p>
                    <span>
                      <Switch checked={true} disabled />
                    </span>
                  </div>
                </AccordionContent>
              </AccordionItem>
              {(
                <AccordionItem value="statistics">
                  <AccordionTrigger>
                    <span>
                      Analíticas{" "}
                      {statisticsAccepted && (
                        <Badge variant="secondary">Activadas</Badge>
                      )}
                    </span>
                  </AccordionTrigger>
                  <AccordionContent>
                    <div className="flex flex-row justify-between gap-4">
                      <p>
                        Estas cookies, propias o de terceros, responden al
                        objetivo de obtener información sobre el rendimiento del
                        Site y la utilización del mismo por parte del usuario,
                        como por ejemplo, realizar la medición y análisis de
                        cómo llegan los usuarios al Site y qué uso hacen del
                        mismo. Asimismo, utilizamos estas cookies para elaborar
                        modelos analíticos sobre la base de tu perfil comercial
                        elaborado por la Entidad.
                      </p>
                      <span>
                        <Switch
                          defaultChecked={preferences.analytics_storage === 'granted'}
                          onCheckedChange={(checked) =>
                            preferencesState.set({
                              ...preferencesState.get(),
                              analytics_storage: checked ? 'granted' : 'denied',
                            })
                          }
                        />
                      </span>
                    </div>
                  </AccordionContent>
                </AccordionItem>
              )}
              {(
                <AccordionItem value="preferences">
                  <AccordionTrigger>
                    <span>
                      Preferencias o Personalización{" "}
                      {preferencesAccepted && (
                        <Badge variant="secondary">Activadas</Badge>
                      )}
                    </span>
                  </AccordionTrigger>
                  <AccordionContent>
                    <div className="flex flex-row justify-between gap-4">
                      <p>
                        Estas cookies permiten recordar información para que el
                        usuario acceda al servicio con determinadas
                        características o que pueden diferenciar su experiencia
                        de la de otros usuarios sin haberlo solicitado
                        expresamente, como por ejemplo, el idioma, en número de
                        resultados a mostrar cuando el usuario realiza una
                        búsqueda, el aspecto o contenido del servicio en función
                        del tipo de navegador.
                      </p>
                      <span>
                        <Switch
                          defaultChecked={preferences.personalization_storage === 'granted'}
                          onCheckedChange={(checked) =>
                            preferencesState.set({
                              ...preferencesState.get(),
                              personalization_storage: checked ? 'granted' : 'denied',
                            })
                          }
                        />
                      </span>
                    </div>
                  </AccordionContent>
                </AccordionItem>
              )}
              {(
                <AccordionItem value="marketing">
                  <AccordionTrigger>
                    <span>
                      Publicidad comportamental{" "}
                      {marketingAccepted && (
                        <Badge variant="secondary">Activadas</Badge>
                      )}
                    </span>
                  </AccordionTrigger>
                  <AccordionContent>
                    <div className="flex flex-row justify-between gap-4">
                      <p>
                        Estas cookies, propias o de terceros, almacenan
                        información del comportamiento del usuario obtenida a
                        través de la observación continuada de sus hábitos de
                        navegación (visitas repetidas a un sitio concreto,
                        interacciones, palabras clave, producción de contenidos
                        en línea, etc.), permitiendo desarrollar un perfil
                        específico para mostrarle publicidad en función del
                        mismo.
                      </p>
                      <span>
                        <Switch
                          defaultChecked={preferences.ad_storage === 'granted'}
                          onCheckedChange={(checked) =>
                            preferencesState.set({
                              ...preferencesState.get(),
                              ad_storage: checked ? 'granted' : 'denied',
                            })
                          }
                        />
                      </span>
                    </div>
                  </AccordionContent>
                </AccordionItem>
              )}
            </Accordion>
          </div>
          <DialogFooter>
            <Button
              variant={"destructive"}
              size={"lg"}
              onClick={() => {
                deniedAll();
              }}
            >
              Rechazar todas
            </Button>
            <DialogTrigger>
              <Button variant={"destructive"} size={"lg"}>
                Guardar preferencias
              </Button>
            </DialogTrigger>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </aside>
  );
}

export function CookieBoardWarningDrawer() {
  const alreadyChosen = useStore(preferencesState).alreadyChosen;
  const [open, setOpen] = useState(alreadyChosen === true ? false : true);

  return (<>
    <Drawer open={open} onOpenChange={setOpen}>
      <DrawerContent>
        <aside className="container mx-auto p-4 xl:grid xl:gap-4 xl:grid-cols-[1fr_auto] xl:items-center">
          <div className="max-xl:pb-4">
            <h2 className="text-2xl text-gray-600">
              ¡No te olvides de las Cookies!
            </h2>
            <p className="text-gray-600">
              Para Universia Holding es importante adaptarse a tus gustos y
              preferencias, para ello usamos cookies propias y de terceros que
              nos permiten medir el volumen y la interacción de los usuarios en
              la web y nos ayudan a mejorarla, permitiéndonos analizar tus
              hábitos y elaborar perfiles de navegación, respetando en todo caso
              tu privacidad. Puedes configurar las cookies, rechazar o
              aceptarlas todas. Este banner se mantendrá activo hasta que
              ejecutes una de las tres opciones. Para más información consulta
              nuestra{" "}
              <a className="text-blue-400" href="/legal/cookies">
                Política de Cookies
              </a>
            </p>
          </div>
          <div className="flex flex-row gap-2">
            <CookieDialogSettings>
              <Button variant="outline">Configurar Cookies</Button>
            </CookieDialogSettings>
            <Button
              variant="outline"
              onClick={() => {
                deniedAll();
                setOpen(false);
              }}
            >
              Rechazar Todas <span>las cookies</span>
            </Button>
            <Button
              variant="outline"
              onClick={() => {
                grantedAll();
                setOpen(false);
              }}
            >
              Aceptar Todas <span>las cookies</span>
            </Button>
          </div>
        </aside>
      </DrawerContent>
    </Drawer>
  </>
  );
}
